parameters.jsCode:
const extractedItems = $input.all();
const downloadItems = $('Download New File').all();
const driveItems = $('Drive: New File Created').all();

const chunkSize = 1200;
const overlap = 200;
const step = chunkSize - overlap;

const itemsOut = [];

for (let itemIndex = 0; itemIndex < extractedItems.length; itemIndex++) {
  const extracted = extractedItems[itemIndex]?.json || {};
  const download = downloadItems[itemIndex]?.json || {};
  const drive = driveItems[itemIndex]?.json || {};

  const originalFileName =
    download.name ||
    extracted.info?.Title ||
    `file_${itemIndex + 1}`;

  const title = originalFileName.replace(/\.[^.]+$/, '');
  const fileId = drive.id || download.id || '';

  const text = extracted.text || '';
  if (!text.trim()) continue;

  for (let i = 0; i < text.length; i += step) {
    const chunk = text.slice(i, i + chunkSize).trim();
    if (!chunk) continue;

    itemsOut.push({
      json: {
        text: `<<<CATEGORIE>>>
${title}
<<<END_CATEGORIE>>>

<<<CONTENT>>>
${chunk}
<<<END_CONTENT>>>`,
        categorie: title,
        original_file_name: originalFileName,
        file_id: fileId,
      }
    });
  }
}

return itemsOut;

